{
  "root_causes": [
    {
      "service": "ts-preserve-service",
      "fault_kind": "http_aborted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name, p.span_name, c.service_name callee, c.span_name callee_span, p.attr_status_code caller_status, c.attr_http_response_status_code callee_http_status, count(*) n FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-preserve-service' AND p.attr_span_kind='Client' AND p.span_name='POST' AND c.service_name='ts-order-service' GROUP BY ALL ORDER BY n DESC",
          "claim": "474 preserve POST calls to order fail with Error status while order's server span for the same call returns 200."
        },
        {
          "kind": "log",
          "sql": "SELECT message, count(*) n FROM abnormal_logs WHERE service_name='ts-preserve-service' AND level='SEVERE' GROUP BY ALL ORDER BY n DESC LIMIT 5",
          "claim": "Preserve logs ResourceAccessException 'Unexpected end of file from server' on POST /api/v1/orderservice/order, 474 times."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-order-service' AND span_name='POST /api/v1/orderservice/order' GROUP BY ALL",
          "claim": "Order's own POST /order server spans show zero errors and about 4.6 ms p95 latency."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-ui-dashboard','ts-preserve-service') AND attr_span_kind='Server' AND span_name LIKE '%preserve%' GROUP BY ALL ORDER BY 1,4 DESC",
          "claim": "Every preserve server span returns 500; ui POST /preserve requests fail with 500 or take about 6.7 s."
        }
      ]
    }
  ]
}

